    ROW("f'(x)", cells=[(0.5, "+", "vert"), (1, "0"), (1.5, "−", "rouge"), (2.5, "−", "rouge"), (3, "0"), (3.5, "+", "vert")], m="ligne_signe", r=("ligne_signe", "le signe de f′(x)")),
    ROW("f(x)", var=[(0, "−∞", "b"), (1, "−2", "h"), (2, "−∞", "b"), (2, "+∞", "h", True), (3, "2", "b"), (4, "+∞", "h")], m="ligne_fleches", r=("ligne_fleches", "les flèches et les limites")),
